solution:
def fewest_coins(coins: list[int], amount: int) -> int:
    INF = amount + 1                     # no real answer uses more than `amount` coins
    best = [0] + [INF] * amount          # best[a] = fewest coins that sum to a
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and best[a - c] + 1 < best[a]:
                best[a] = best[a - c] + 1    # last coin c on top of the best pile for a - c
    return best[amount] if best[amount] < INF else -1

perf.naive:
def fewest_coins(coins: list[int], amount: int) -> int:
    def fewest(a):                       # re-solves the same smaller amounts again and again
        if a == 0:
            return 0
        best = -1
        for c in coins:
            if c <= a:
                sub = fewest(a - c)
                if sub != -1 and (best == -1 or sub + 1 < best):
                    best = sub + 1
        return best
    return fewest(amount)
